import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const q=JSON.parse('{"title":"第106章 前街口","description":"","frontmatter":{},"headers":[],"relativePath":"第106章_前街口.md","filePath":"第106章_前街口.md"}'),_={name:"第106章_前街口.md"};function r(n,p,s,u,c,i){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第106章-前街口" tabindex="-1">第106章 前街口 <a class="header-anchor" href="#第106章-前街口" aria-label="Permalink to &quot;第106章 前街口&quot;">​</a></h1><p>那年秋天我去了趟雾山。</p><p>去干什么很小。</p><p>一个客人。</p><p>她那一批货里有一件东西，是限量的，编号那种。</p><p>那个客人住雾山，她那边的快递不上门。</p><p>我们那天对单的时候她说了一句，这个人在雾山。</p><p>我说，我去。</p><p>她说，你去干什么，你寄过去。</p><p>我说，寄过去万一又编号错了，我上次漏发过一件。</p><p>她说，那是我这边挪走的。</p><p>我说，反正我这边也说不清。</p><p>她说，你别自己跑，这一趟车票加吃饭两百多。</p><p>我说，我今天手上有。</p><p>她说，你手上有多少。</p><p>我说，你别算我的。</p><p>她说，行。</p><p>她说，你到了你给我发一条。</p><p>我说，我到了给你发货单。</p><p>她说，一样。</p><p>她是九月十四号那天讲这句话的。</p><p>我当时不知道她讲&quot;一样&quot;这两个字是什么意思。</p><p>后来我明白了：她那天把&quot;你给我发一条&quot;改成&quot;给我发货单&quot;，是因为她不想在这句话里跟我讲&quot;你到了告诉我一声&quot;。</p><p>那一句她讲不出来。</p><p>她只能把它变成一个公事。</p><p>雾山这个城市我上一次来是考试。</p><p>那年我们全年级出去，我没去成那个什么研学，我在家里补作业。</p><p>我来雾山那年是去考一个什么证，考完我当天下午就走了。</p><p>这次不一样。</p><p>这次我是来送一件东西。</p><p>那天下午两点我在火车站外面站着。</p><p>我把那个小盒子从包里拿出来看了一遍。</p><p>盒子上贴着一张便利贴，上面写的是那个客人的地址，一串数字。</p><p>那个地址在一个老街上。</p><p>我打了车。</p><p>那个司机把我放在街口。</p><p>他说，进不去，你们这种地方现在都封着。</p><p>我说，什么叫封着。</p><p>他说，后头那条街在修，围挡围了半年。</p><p>他说，你要找人，你到前街口那个糖水小车那儿问。</p><p>我那天走错了两次。</p><p>第一次我走进一个卖五金的门口，我以为那是那条街。</p><p>第二次我走到一个中学后面，那边有一排卖文具的。</p><p>前街口那个小车在。</p><p>那是一个很旧的不锈钢的车，顶上撑着一块蓝布。</p><p>车上挂着十几样东西，红豆、绿豆、银耳、桃胶。</p><p>后面有一个塑料棚，棚下有四张桌子。</p><p>那张塑料棚下面有两个人在吃东西。</p><p>我走到那个车前面。</p><p>开车的是一个女的，六十岁往上了，头发剪很短。</p><p>她说，你要什么。</p><p>我说，我问个地址。</p><p>她说，你讲。</p><p>我把那个数字讲了一遍。</p><p>她摇头。</p><p>她说，这一串我认不出来。</p><p>她说，我们这边门牌今年重新编了。</p><p>她说，你问这个干什么。</p><p>我说，我送东西。</p><p>她说，你送什么东西自己跑。</p><p>我说，顺手。</p><p>她说，你顺手你从哪儿来。</p><p>我说，澄江。</p><p>她说，澄江你跑到这里送一个东西。</p><p>她说完这句，她把那个勺子放下来。</p><p>她往我后面看。</p><p>她看的是那排围挡。</p><p>她说，你以前来过这里吗。</p><p>我说，来过一次，考试。</p><p>她说，你考试你记得我们这里有个后街？</p><p>我说，我不记得。</p><p>她说，那时候还没有这个围挡。</p><p>她说，那时候里头那个棚子还在。</p><p>她说，我们这里那几年有一个棚子，就在你现在站的这个后面十米。</p><p>她说，棚子里头有六张桌子。</p><p>她说，那几年有一个学生，老爱坐角落那一张。</p><p>她说，一个人。</p><p>她说，来得很稳。</p><p>我说，他吃什么。</p><p>她说，他不吃什么。</p><p>她说，他买一碗最便宜的，坐一个钟头。</p><p>她说，我那时候说他一次，我说你这样坐着我要收你位子的钱。</p><p>她说，他耳朵红。</p><p>她说，他第二个月还来。</p><p>她说，他来了三年。</p><p>她说，后来他就不来了。</p><p>我说，他去哪儿了。</p><p>她说，我不知道。</p><p>她说，我们这种人不知道这些小孩去哪儿。</p><p>她说，我只知道有一个来了三年。</p><p>她说，我这个人我这几年就记住了一个耳朵红的小孩。</p><p>那天我在小车前面站了大概两分钟。</p><p>我把那个地址给她看，我说我打错了。</p><p>我说我找一个门牌。</p><p>她说，你到那个路口往左，有一个新的牌子。</p><p>我按她讲的走，找到了。</p><p>那个客人是一个五十来岁的男的。</p><p>他把那个盒子收了，他数了一遍。</p><p>他说，你专门跑一趟。</p><p>我说，顺手。</p><p>他说，你这孩子。</p><p>那天下午四点我往回走。</p><p>我走过那个前街口。</p><p>那辆小车还在，蓝布被风吹得鼓起来。</p><p>我在那里等那个车，我等了一个钟头。</p><p>我等的不是那个客人。</p><p>我是在算一件事。</p><p>我在算一个人连续三年每周来一次同一个地方，坐同一张桌子，要费多大劲。</p><p>我算不出来。</p><p>我只知道我这辈子做过的最稳的一件事是每天十二点看一次手机。</p><p>我跟她说过这个吗。</p><p>我没说过。</p><p>那天晚上我回到澄江，八点。</p><p>我在地铁上把那个小盒子空出来的位置，拿一张纸填上了。</p><p>我填的不是东西。</p><p>我是手上拿着一个空盒子，我不塞点东西我不会走路。</p><p>我给她发了一条。</p><p>我说，送到了，编号对。</p><p>她说，好。</p><p>她说，你今天跑了一趟。</p><p>我说，嗯。</p><p>她说，车费我明天转你。</p><p>我说，不用。</p><p>她说，你要。</p><p>她说，你不要你明天心里有这一笔。</p><p>我说，我今天心里已经有一笔了。</p><p>她说，什么。</p><p>我说，我今天在雾山一个糖水摊上问路，那个婆婆跟我讲了一个学生。</p><p>她说，讲他什么。</p><p>我说，讲他来了三年，耳朵红，买最便宜的一碗。</p><p>她隔了很久。</p><p>她说，你干嘛跟我讲这个。</p><p>我说，我今天在车上想了一晚上，我不知道我为什么要跟你讲这个。</p><p>她说，那你不讲。</p><p>我说，我已经讲了。</p><p>她说，那你把这一笔也记在本上。</p><p>我说，我记。</p><p>她说，你别写我的名字。</p><p>我说，我没写。</p><p>她说，你今天写的是别人。</p><p>她说，你写别人你就写清楚，你说&quot;雾山，一个耳朵红的人，来了三年&quot;。</p><p>她说，你不要在后面补一句&quot;我算不出来&quot;。</p><p>她说，你一补那一句，别人就变成你的了。</p><p>我说，那我不补。</p><p>她说，你肯定会补。</p><p>她说，你这一辈子你写的每一页都在最后补那一句。</p>',146)])])}const l=t(_,[["render",r]]);export{q as __pageData,l as default};
